#include "karplus_test_access.hpp"
#include <fstream>
#include <vector>
#include <iostream>
#include <stdexcept>
using namespace mfrk::karplus;
#include "karplus_fixture_reader.hpp"
using Reader=FixtureReader;
struct Counts {std::uint64_t blocks=0,prepared=0,state=0,buffers=0,seed=0,raw=0,decoded=0,scaled=0,excitation=0;};
void block(Reader&r,Engine&e,Memory&m,SharedRandom&random,std::array<std::int16_t,8192>&expected,Counts&c){Input in;in.frequency_hz=F(r.read<std::uint32_t>());in.note=F(r.read<std::uint32_t>());in.words=r.read<std::array<std::uint16_t,3>>();in.dirty=r.read<std::array<std::uint8_t,3>>();in.trigger_event=r.read<std::uint8_t>();const auto interface=r.read<std::uint8_t>();if(in.trigger_event>2||interface>1)throw std::runtime_error("input flag");in.interface_prepare=interface!=0;in.level=F(r.read<std::uint32_t>());
 const auto prepared=r.read<std::array<std::uint8_t,288>>(),after=r.read<std::array<std::uint8_t,288>>();const auto seed=r.read<std::uint32_t>();const auto raw=r.read<std::array<std::int16_t,32>>();const auto decoded=r.read<std::array<std::uint32_t,32>>(),scaled=r.read<std::array<std::uint32_t,32>>();const auto flag=r.read<std::uint8_t>();if(flag>1)throw std::runtime_error("excitation flag");std::array<std::int16_t,32> excite{};if(flag)excite=r.read<std::array<std::int16_t,32>>();const auto changes=r.read<std::uint16_t>();if(changes>8192)throw std::runtime_error("delta count");int last=-1;for(unsigned i=0;i<changes;++i){const auto index=r.read<std::uint16_t>();if(index>=8192||index<=last)throw std::runtime_error("delta index");last=index;expected[index]=r.read<std::int16_t>();}
 TestAccess::inputs(e,in);for(unsigned i=0;i<288;++i)c.prepared+=TestAccess::state(e)[i]!=prepared[i];std::array<float,32> output{};if(e.try_process(in,output)!=Status::ok)throw std::runtime_error("render status");for(unsigned i=0;i<288;++i)c.state+=TestAccess::state(e)[i]!=after[i];for(unsigned i=0;i<8192;++i)c.buffers+=m.samples[i]!=expected[i];c.seed+=random.value!=seed;for(unsigned i=0;i<32;++i){c.raw+=TestAccess::raw(e)[i]!=raw[i];const float x=static_cast<float>(TestAccess::raw(e)[i])*F(939524352);c.decoded+=std::bit_cast<std::uint32_t>(x)!=decoded[i];c.scaled+=std::bit_cast<std::uint32_t>(output[i])!=scaled[i];if(flag)c.excitation+=TestAccess::excite(e)[i]!=excite[i];}++c.blocks;
}
int main(int argc,char**argv)try{if(argc!=2)return 2;Reader r(argv[1]);if(r.read<std::array<char,8>>()!=std::array<char,8>{'K','R','P','L','0','0','0','2'})return 2;Tables tables;std::uint64_t terr=0,ctorerr=0;for(auto x:TestAccess::coefficients(tables))terr+=x!=r.read<std::int32_t>();if(r.read<std::uint32_t>()!=4)return 2;
 for(int i=0;i<4;++i){if(r.read<std::uint8_t>()>1)return 2;const auto fill=r.read<std::uint8_t>();if(fill!=0&&fill!=165)return 2;SharedRandom random{54321};Memory memory{};auto e=Engine::admitted_zero_arena(tables,random,memory);TestAccess::fill_constructor(e,fill);for(auto x:TestAccess::state(e))ctorerr+=x!=r.read<std::uint8_t>();e.bind(0x400020000ull,8192);e.initialize();for(auto x:TestAccess::state(e))ctorerr+=x!=r.read<std::uint8_t>();const auto mask=r.read<std::array<std::uint8_t,288>>();unsigned n=0;for(auto x:mask){if(x>1)return 2;n+=x;}if(n!=173)return 2;}
 Counts c;const auto cases=r.read<std::uint32_t>();if(!cases||cases>100)return 2;
 for(unsigned i=0;i<cases;++i){if(r.read<std::uint8_t>()>1)return 2;SharedRandom random{r.read<std::uint32_t>()};const auto n=r.read<std::uint32_t>();if(!n||n>10000)return 2;Memory m{};auto e=Engine::admitted_zero_arena(tables,random,m);e.bind(0x400020000ull,8192);e.initialize();std::array<std::int16_t,8192> expected{};for(unsigned j=0;j<n;++j)block(r,e,m,random,expected,c);}
 SharedRandom random{r.read<std::uint32_t>()};const auto n=r.read<std::uint32_t>();if(!n||n>10000)return 2;Memory ma{},mb{};auto a=Engine::admitted_zero_arena(tables,random,ma),b=Engine::admitted_zero_arena(tables,random,mb);a.bind(0x400020000ull,8192);b.bind(0x400028000ull,8192);a.initialize();b.initialize();std::array<std::int16_t,8192> ea{},eb{};
 for(unsigned i=0;i<n;++i){const auto side=r.read<std::uint8_t>();if(side>1)return 2;if(side)block(r,b,mb,random,eb,c);else block(r,a,ma,random,ea,c);}r.end();
 std::cout<<"{\"blocks\":"<<c.blocks<<",\"tables\":"<<terr<<",\"constructor\":"<<ctorerr<<",\"prepared\":"<<c.prepared<<",\"state\":"<<c.state<<",\"buffers\":"<<c.buffers<<",\"seed\":"<<c.seed<<",\"raw\":"<<c.raw<<",\"decoded\":"<<c.decoded<<",\"scaled\":"<<c.scaled<<",\"excitation\":"<<c.excitation<<"}\n";return terr||ctorerr||c.prepared||c.state||c.buffers||c.seed||c.raw||c.decoded||c.scaled||c.excitation?1:0;
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}
